function bookingSortValue(b,key){
  switch(key){
    case 'reference':return b.reference||'';
    case 'guest':return b.guest_name||'';
    case 'apartment':return b.apartment_name||'';
    case 'arrival':return b.arrival||'';
    case 'source':return b.booking_channel_name||b.source||'';
    case 'accounting':return accountingModeLabel(accountingModeValue(b));
    case 'price':return Number(b.total_price||0);
    case 'status':return statusLabel(b.status);
    default:return '';
  }
}
