document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(!(form instanceof HTMLFormElement))return;const formName=formIdentifier(form);const submit=formName?document.querySelector(`[type="submit"][form="${CSS.escape(formName)}"]`):null;const submitButton=submit||form.querySelector('[type="submit"]');if(submitButton)submitButton.disabled=true;if(form.closest('#modalRoot')){window.stayPilotModal.clearError();window.stayPilotModal.setBusy(true)}try{
  if(await handleSupplementalSubmit(form))return;
  if(formName==='apartmentForm'){await api('save_apartment',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast('Apartment gespeichert.');state.cache.apartments=null;return renderApartments()}
  if(formName==='guestForm'){const out=await api('save_guest',{method:'POST',data:formObject(form)});toast('Gast gespeichert.');state.cache.guests=null;await loadBasics(true);window.stayPilotModal.markClean();if(state.returnBookingDraft){const draft=state.returnBookingDraft;state.returnBookingDraft=null;draft.guest_id=out.id;return openBooking(Number(draft.id||0),{bookingData:draft})}if(state.returnBookingId){const id=state.returnBookingId;state.returnBookingId=0;return openBooking(id)}closeModal(true);return state.page==='guests'?renderGuests():null}
  if(form.classList.contains('category-form')){const out=await api('save_guest_category',{method:'POST',data:formObject(form)});toast(out.message);state.cache.categories=null;window.stayPilotModal.markClean();return openCategories()}
  if(formName==='bookingForm'){await api('save_booking',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast('Buchung gespeichert.');state.cache.guests=null;return renderPage()}
  if(formName==='moveConfirmForm')return executeMove(form);
  if(formName==='taskForm'){await api('save_task',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast('Aufgabe gespeichert.');return renderHousekeeping()}
  if(formName==='priceForm'){const apartments=[...form.querySelectorAll('[data-price-row]')].map(r=>({id:r.dataset.priceRow,base_price:r.querySelector('[name=base_price]').value,cleaning_fee:r.querySelector('[name=cleaning_fee]').value,breakfast_price:r.querySelector('[name=breakfast_price]').value,half_board_price:r.querySelector('[name=half_board_price]').value}));const r=await api('save_prices',{method:'POST',data:{apartments}});toast(r.message);return renderPrices()}
  if(formName==='seasonForm'){await api('save_season',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast('Saison gespeichert.');return renderPrices()}
  if(formName==='blockForm'){await api('save_block',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast('Sperrzeit gespeichert.');return renderPrices()}
  if(formName==='csvPreviewForm'){const fd=new FormData(form);const d=await api('csv_preview',{method:'POST',formData:fd});showCsvMapping(d);return}
  if(form.classList.contains('integrationForm')){const o=formObject(form),provider=form.dataset.provider,settings={};if(provider==='hotel_spider'){['health_path','reservations_path','availability_path','auth_header','auth_prefix'].forEach(k=>{settings[k]=o[k];delete o[k]})}o.provider=provider;o.settings=settings;const r=await api('save_integration',{method:'POST',data:o});toast(r.message);return renderIntegrations()}
  if(formName==='settingsForm'){const r=await api('save_settings',{method:'POST',data:formObject(form)});toast(r.message);document.getElementById('brandProperty').textContent=form.property_name.value;return renderSettings()}
  if(formName==='passwordForm'){const r=await api('change_password',{method:'POST',data:formObject(form)});toast(r.message);form.reset();return}
}catch(err){toast(err.message,'error');if(form.closest('#modalRoot'))window.stayPilotModal.showError(err.message)}finally{if(submitButton)submitButton.disabled=false;if(window.stayPilotModal.opened)window.stayPilotModal.setBusy(false)}});

async function runCsvImport(){if(!state.csv)return;const mapping={};document.querySelectorAll('[data-map-target]').forEach(x=>mapping[x.dataset.mapTarget]=x.value);const defaults={status:document.getElementById('csvDefaultStatus')?.value||'confirmed',source:document.getElementById('csvDefaultSource')?.value||'CSV'};if(!confirm('CSV-Import jetzt starten? Vorhandene Referenzen/Codes können aktualisiert werden.'))return;const r=await api('csv_import',{method:'POST',data:{token:state.csv.token,entity_type:state.csv.entity_type,delimiter:state.csv.delimiter,date_format:document.getElementById('csvDateFormat').value,decimal_separator:document.getElementById('csvDecimal').value,profile_name:document.getElementById('csvProfileName').value,mapping,defaults}});toast(r.message);if(r.errors?.length)modal('Import abgeschlossen',`<div class="alert warning"><b>${esc(r.message)}</b></div><ul>${r.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,`<button class="btn primary" data-action="close-modal">Schließen</button>`);else renderCsv()}
async function saveMappings(provider){const mappings=[...document.querySelectorAll(`[data-map-provider="${provider}"]`)].map(r=>({local_id:r.dataset.localId,external_id:r.querySelector('[data-map-external]').value,secondary_external_id:r.querySelector('[data-map-secondary]').value}));const out=await api('save_mappings',{method:'POST',data:{provider,mappings}});toast(out.message)}

// Kalender-Kurzinformationen: reine Anzeige, ohne eigene Klick- oder Drag-Steuerung.
let calendarTooltipElement=null;
function ensureCalendarTooltip(){if(calendarTooltipElement?.isConnected)return calendarTooltipElement;calendarTooltipElement=document.createElement('div');calendarTooltipElement.className='calendar-booking-tooltip';calendarTooltipElement.setAttribute('role','tooltip');calendarTooltipElement.hidden=true;document.body.appendChild(calendarTooltipElement);return calendarTooltipElement}
function decodeCalendarTooltip(item){try{return JSON.parse(decodeURIComponent(item.dataset.calendarTooltip||''))}catch{return null}}
function calendarTooltipHtml(data){
  const services=[data.breakfast?'☕ Frühstück':'',data.half_board?'🍽️ Halbpension':''].filter(Boolean).join(' · ')||'Keine Verpflegung hinterlegt';
  const persons=[`${data.adults||0} Erw.`,data.children?`${data.children} Kinder`:'',data.babies?`${data.babies} Babys`:''].filter(Boolean).join(' · ');
  const notes=String(data.internal_notes||'').trim();
  return `<div class="calendar-tooltip-head"><div><strong>${esc(data.guest_name)}</strong><small>${esc(data.reference||'Ohne Referenz')}</small></div><span class="calendar-tooltip-status ${esc(data.status)}">${esc(calendarStatusLabel(data.status))}</span></div><div class="calendar-tooltip-category"><i style="--cat:${esc(data.category_color||'#64748b')}"></i>${esc(data.category||'Keine Kategorie')}${data.is_upgrade?'<span class="calendar-upgrade-badge">⬆ Upgrade</span>':''}</div><dl><div><dt>Apartment</dt><dd>${esc([data.apartment_code,data.apartment_name].filter(Boolean).join(' · ')||'Nicht zugeordnet')}</dd></div><div><dt>Aufenthalt</dt><dd>${fmtDate(data.arrival)} – ${fmtDate(data.departure)} · ${Number(data.nights||0)} Nächte</dd></div><div><dt>Personen</dt><dd>${esc(persons||'Keine Angaben')}</dd></div><div><dt>Quelle</dt><dd>${esc(data.source||'–')}</dd></div><div><dt>Leistungen</dt><dd>${esc(services)}</dd></div><div><dt>Preis</dt><dd>${fmtMoney(data.total_price)} · offen ${fmtMoney(data.open_amount)}</dd></div>${notes?`<div class="calendar-tooltip-note"><dt>Interne Notiz</dt><dd>${esc(notes.length>180?notes.slice(0,177)+'…':notes)}</dd></div>`:''}</dl><div class="calendar-tooltip-hint">Klicken öffnet die vollständige Buchung.</div>`;
}
function positionCalendarTooltip(item){const tip=ensureCalendarTooltip(),rect=item.getBoundingClientRect(),gap=10;tip.style.left='8px';tip.style.top='8px';const width=tip.offsetWidth,height=tip.offsetHeight;let left=rect.left+rect.width/2-width/2,top=rect.top-height-gap;left=Math.max(8,Math.min(window.innerWidth-width-8,left));if(top<8)top=rect.bottom+gap;if(top+height>window.innerHeight-8)top=Math.max(8,rect.top-height-gap);tip.style.left=`${Math.round(left)}px`;tip.style.top=`${Math.round(top)}px`}
function showCalendarTooltip(item){if(state.pointer||!item?.dataset.calendarTooltip)return;const data=decodeCalendarTooltip(item);if(!data)return;const tip=ensureCalendarTooltip();tip.innerHTML=calendarTooltipHtml(data);tip.hidden=false;tip.dataset.owner=String(item.dataset.bookingId||'');requestAnimationFrame(()=>positionCalendarTooltip(item))}
function hideCalendarTooltip(){if(calendarTooltipElement){calendarTooltipElement.hidden=true;calendarTooltipElement.dataset.owner=''}}
document.addEventListener('mouseover',event=>{if(!window.matchMedia('(hover:hover)').matches)return;const item=event.target.closest?.('[data-calendar-tooltip]');if(!item||item.contains(event.relatedTarget))return;showCalendarTooltip(item)});
document.addEventListener('mouseout',event=>{const item=event.target.closest?.('[data-calendar-tooltip]');if(!item||item.contains(event.relatedTarget))return;hideCalendarTooltip()});
document.addEventListener('focusin',event=>{const item=event.target.closest?.('[data-calendar-tooltip]');if(item)showCalendarTooltip(item)});
document.addEventListener('focusout',event=>{const item=event.target.closest?.('[data-calendar-tooltip]');if(item)hideCalendarTooltip()});
document.addEventListener('pointerdown',hideCalendarTooltip,true);
document.addEventListener('scroll',hideCalendarTooltip,true);

// Kalendersteuerung: eine einzige Pointer-Implementierung für Maus, Touch und Stift.
function bookingById(id){return [...(state.calendarData?.bookings||[]),...(state.calendarData?.waiting||[])].find(x=>Number(x.id)===Number(id))||null}
function clearCalendarPointer(pointer=null){
  const p=pointer||state.pointer;
  if(p?.source&&p.pointerId!==undefined){try{if(p.source.hasPointerCapture?.(p.pointerId))p.source.releasePointerCapture(p.pointerId)}catch(_){} }
  if(!pointer||state.pointer===pointer)state.pointer=null;
  document.body.classList.remove('dragging-mode');
  p?.ghost?.remove();
  document.querySelectorAll('.drop-active').forEach(x=>x.classList.remove('drop-active'));
}
function calendarCellAtPoint(x,y){
  const grid=document.querySelector('.calendar-grid');
  if(!grid||!state.calendarData)return null;
  const row=[...grid.querySelectorAll('[data-apartment-row]')].find(element=>{const rect=element.getBoundingClientRect();return y>=rect.top&&y<=rect.bottom});
  if(!row)return null;
  const cells=[...row.querySelectorAll('[data-calendar-cell]')];
  let cell=cells.find(element=>{const rect=element.getBoundingClientRect();return x>=rect.left&&x<rect.right});
  if(cell)return cell;
  // An den Pixelgrenzen das nächstliegende sichtbare Tagesfeld verwenden.
  const candidates=cells.map(element=>{const rect=element.getBoundingClientRect();return {element,distance:x<rect.left?rect.left-x:x>rect.right?x-rect.right:0,visible:rect.right>0&&rect.left<window.innerWidth}}).filter(item=>item.visible);
  candidates.sort((a,b)=>a.distance-b.distance);
  return candidates[0]?.distance<=3?candidates[0].element:null;
}
document.addEventListener('pointerdown',event=>{
  const resize=event.target.closest('[data-resize]');
  const move=event.target.closest('[data-move]');
  if(!resize&&!move)return;
  if(event.pointerType==='mouse'&&event.button!==0)return;
  const holder=event.target.closest('[data-booking-id]');
  if(!holder)return;
  const interactive=event.target.closest('button,a,input,select,textarea,label,[contenteditable="true"]');
  if(!resize&&interactive&&!event.target.closest('[data-drag-handle]'))return;
  const id=Number(holder.dataset.bookingId),booking=bookingById(id);
  if(!booking)return;
  const type=resize?`resize-${resize.dataset.resize}`:'move';
  state.pointer={id,type,booking,startX:event.clientX,startY:event.clientY,active:false,source:holder,target:null,ghost:null,pointerId:event.pointerId};
});
document.addEventListener('pointermove',event=>{
  const pointer=state.pointer;
  if(!pointer||event.pointerId!==pointer.pointerId)return;
  if(!pointer.active&&Math.hypot(event.clientX-pointer.startX,event.clientY-pointer.startY)<7)return;
  if(!pointer.active){
    pointer.active=true;
    try{pointer.source.setPointerCapture?.(event.pointerId)}catch(_){}
    document.body.classList.add('dragging-mode');
    pointer.ghost=pointer.source.cloneNode(true);
    pointer.ghost.removeAttribute('data-action');
    pointer.ghost.removeAttribute('tabindex');
    pointer.ghost.removeAttribute('role');
    pointer.ghost.classList.add('booking-ghost');
    pointer.ghost.style.width=Math.max(150,pointer.source.getBoundingClientRect().width)+'px';
    pointer.ghost.querySelectorAll('.resize-handle,.drag-grip').forEach(x=>x.remove());
    document.body.appendChild(pointer.ghost);
  }
  if(event.cancelable)event.preventDefault();
  pointer.ghost.style.left=event.clientX+'px';
  pointer.ghost.style.top=event.clientY+'px';
  document.querySelectorAll('.drop-active').forEach(x=>x.classList.remove('drop-active'));
  pointer.ghost.style.display='none';
  const under=document.elementFromPoint(event.clientX,event.clientY);
  pointer.ghost.style.display='';
  pointer.target=under?.closest?.('[data-unassign-zone]')||calendarCellAtPoint(event.clientX,event.clientY);
  if(pointer.target?.matches('[data-calendar-cell],[data-unassign-zone]'))pointer.target.classList.add('drop-active');
  const shell=document.getElementById('calendarShell');
  if(shell){
    const rect=shell.getBoundingClientRect();
    if(event.clientX>rect.right-45)shell.scrollLeft+=16;else if(event.clientX<rect.left+45)shell.scrollLeft-=16;
    if(event.clientY>rect.bottom-45)shell.scrollTop+=12;else if(event.clientY<rect.top+45)shell.scrollTop-=12;
  }
},{passive:false});
document.addEventListener('pointerup',async event=>{
  const pointer=state.pointer;
  if(!pointer||event.pointerId!==pointer.pointerId)return;
  clearCalendarPointer(pointer);
  if(!pointer.active)return;
  state.suppressClickUntil=Date.now()+700;
  try{
    if(pointer.type==='move'&&pointer.target?.matches('[data-unassign-zone]')){
      if(confirm(`${pointer.booking.guest_name} wirklich in „Nicht zugeordnet“ verschieben?`)){
        const out=await api('unassign_booking',{method:'POST',data:{id:pointer.id}});
        toast(out.message);
        await renderCalendar();
      }
      return;
    }
    if(!pointer.target?.matches('[data-calendar-cell]'))return;
    let targetArrival=pointer.target.dataset.date,targetDeparture='';
    if(pointer.type==='resize-left'){targetArrival=pointer.target.dataset.date;targetDeparture=pointer.booking.departure}
    else if(pointer.type==='resize-right'){targetArrival=pointer.booking.arrival;targetDeparture=addDays(pointer.target.dataset.date,1)}
    await openMoveConfirmation({id:pointer.id,booking:pointer.booking,targetApartmentId:pointer.target.dataset.apartmentId,targetArrival,targetDeparture,mode:pointer.type.startsWith('resize')?'resize':'move'});
  }catch(error){toast(error.message,'error')}
});
document.addEventListener('pointercancel',event=>{const pointer=state.pointer;if(pointer&&event.pointerId===pointer.pointerId)clearCalendarPointer(pointer)});
document.addEventListener('keydown',event=>{
  const item=event.target.closest?.('[role="button"][data-action="edit-booking"]');
  if(!item||!['Enter',' '].includes(event.key))return;
  event.preventDefault();
  if(Date.now()>=state.suppressClickUntil)openBooking(item.dataset.id);
});

