function housekeepingSortValue(t,key){
  switch(key){
    case 'date':return t.task_date||'';
    case 'apartment':return `${t.apartment_code||''} ${t.apartment_name||''}`;
    case 'type':return taskTypeLabel(t.task_type);
    case 'guest':return t.guest_name||'';
    case 'assigned':return t.assigned_to||'';
    case 'minutes':return Number(t.estimated_minutes||0);
    case 'status':return statusLabel(t.status);
    default:return '';
  }
}
async function renderHousekeeping(){
  const p={from:state.houseFrom,to:state.houseTo,...state.houseFilters};const d=await api('housekeeping',{params:p});state.cache.tasks=d.tasks;state.cache.apartments=d.apartments;state.cache.houseStaff=d.staff||[];
  const opts=(arr,val,label='Alle')=>`<option value="">${label}</option>${arr.map(x=>`<option value="${esc(x[0]??x)}" ${String(x[0]??x)===String(val)?'selected':''}>${esc(x[1]??x)}</option>`).join('')}`;
  const tasks=state.housekeepingSort?sortRows(d.tasks,t=>housekeepingSortValue(t,state.housekeepingSort),state.housekeepingSortDir||'asc'):d.tasks;
  content.innerHTML=`<div class="toolbar report-toolbar"><label>Von<input type="date" id="houseFrom" value="${esc(d.from)}"></label><label>Bis<input type="date" id="houseTo" value="${esc(d.to)}"></label><label>Wohnung<select id="houseApartment">${opts(d.apartments.map(a=>[a.id,`${a.code} – ${a.name}`]),state.houseFilters.apartment_id)}</select></label><label>Status<select id="houseStatus">${opts([['open','Offen'],['planned','Geplant'],['in_progress','In Arbeit'],['done','Erledigt']],state.houseFilters.status)}</select></label><label>Aufgabe<select id="houseType">${opts([['turnover','Wechselreinigung'],['stayover','Zwischenreinigung'],['deep_clean','Grundreinigung'],['maintenance','Wartung'],['inspection','Kontrolle']],state.houseFilters.task_type)}</select></label><label>Zuständig<select id="houseStaff">${opts((d.staff||[]).map(x=>[x,x]),state.houseFilters.assigned_to)}</select></label><label>Priorität<select id="housePriority">${opts([['low','Niedrig'],['normal','Normal'],['high','Hoch'],['urgent','Dringend']],state.houseFilters.priority)}</select></label><button type="button" class="btn" data-action="house-apply-v2">Anzeigen</button><button type="button" class="btn success" data-action="generate-housekeeping">⚙ Aus Abreisen erzeugen</button><button type="button" class="btn primary" data-action="new-task">＋ Aufgabe</button><div class="spacer"></div><button type="button" class="btn" data-action="print-housekeeping">🖨 Nach Vorgaben drucken</button></div><div class="grid kpis compact-kpis"><div class="card kpi"><div class="kpi-label">Aufgaben</div><div class="kpi-value">${d.tasks.length}</div></div><div class="card kpi"><div class="kpi-label">Offen</div><div class="kpi-value">${d.tasks.filter(t=>t.status!=='done').length}</div></div><div class="card kpi"><div class="kpi-label">Geplante Zeit</div><div class="kpi-value">${d.tasks.reduce((s,t)=>s+Number(t.estimated_minutes||0),0)} Min.</div></div></div><div class="card"><div class="table-wrap"><table><thead><tr>${sortTh('Datum','date','housekeeping')}${sortTh('Wohnung','apartment','housekeeping')}${sortTh('Aufgabe','type','housekeeping')}${sortTh('Gast / Buchung','guest','housekeeping')}${sortTh('Zuständig','assigned','housekeeping')}${sortTh('Zeit','minutes','housekeeping')}<th>Wäsche</th>${sortTh('Status','status','housekeeping')}<th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><b>${fmtDate(t.task_date)}</b></td><td>${esc(t.apartment_code)} · ${esc(t.apartment_name)}</td><td>${esc(taskTypeLabel(t.task_type))}<br><span class="muted small">${esc(t.notes||'')}</span></td><td>${esc(t.guest_name||'–')}<br><span class="muted small">${esc(t.reference||'')}</span></td><td>${esc(t.assigned_to||'Noch offen')}</td><td>${Number(t.estimated_minutes||0)} Min.</td><td>${Number(t.linen_change)?'Bett ':''}${Number(t.towel_change)?'Handtücher':''}</td><td><select data-task-status="${t.id}">${[['open','Offen'],['planned','Geplant'],['in_progress','In Arbeit'],['done','Erledigt']].map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></td><td><button type="button" class="btn small" data-action="edit-task" data-id="${t.id}">Bearbeiten</button> <button type="button" class="btn small danger" data-action="delete-task" data-id="${t.id}">Löschen</button></td></tr>`).join('')||'<tr><td colspan="9">Keine Aufgaben nach diesen Vorgaben.</td></tr>'}</tbody></table></div></div>`;
}

async function openTask(id=0){
  await loadBasics();let t={id:0,apartment_id:'',booking_id:'',task_date:APP.today,task_type:'turnover',status:'open',assigned_to:'',priority:'normal',estimated_minutes:60,linen_change:1,towel_change:1,checklist:['Bad reinigen','Küche prüfen','Bettwäsche wechseln','Handtücher wechseln','Böden reinigen','Müll entsorgen','Endkontrolle'],supplies:'',supervisor:'',notes:''};if(id)t=state.cache.tasks.find(x=>Number(x.id)===Number(id))||t;
  const checklist=Array.isArray(t.checklist)?t.checklist.join('\n'):'';
  modal(id?'Reinigungsaufgabe bearbeiten':'Aufgabe anlegen',`<form id="taskForm"><input type="hidden" name="id" value="${t.id}"><div class="form-grid">${selectField('Wohnung *','apartment_id',state.cache.apartments.map(a=>[a.id,`${a.code} – ${a.name}`]),t.apartment_id,'required')}${field('Datum *','task_date',t.task_date,'date','required')}${selectField('Aufgabe','task_type',[['turnover','Wechselreinigung'],['stayover','Zwischenreinigung'],['deep_clean','Grundreinigung'],['maintenance','Wartung'],['inspection','Kontrolle']],t.task_type)}${selectField('Status','status',[['open','Offen'],['planned','Geplant'],['in_progress','In Arbeit'],['done','Erledigt']],t.status)}${field('Zuständig','assigned_to',t.assigned_to||'')}${field('Kontrolle durch','supervisor',t.supervisor||'')}${selectField('Priorität','priority',[['low','Niedrig'],['normal','Normal'],['high','Hoch'],['urgent','Dringend']],t.priority)}${field('Geschätzte Minuten','estimated_minutes',t.estimated_minutes||60,'number','min="0"')}<label class="info-box"><input type="checkbox" name="linen_change" value="1" ${Number(t.linen_change)?'checked':''}> Bettwäsche wechseln</label><label class="info-box"><input type="checkbox" name="towel_change" value="1" ${Number(t.towel_change)?'checked':''}> Handtücher wechseln</label><div class="field span-2"><label>Checkliste – ein Punkt pro Zeile</label><textarea name="checklist">${esc(checklist)}</textarea></div><div class="field span-2"><label>Benötigtes Material</label><textarea name="supplies">${esc(t.supplies||'')}</textarea></div><div class="field span-2"><label>Notizen</label><textarea name="notes">${esc(t.notes||'')}</textarea></div></div></form>`,`<button type="button" class="btn" data-action="close-modal">Abbrechen</button><button class="btn primary" type="submit" form="taskForm">Speichern</button>`,true);
}

function mealBookingSortValue(b,key){
  switch(key){
    case 'guest':return b.guest_name||'';
    case 'apartment':return b.apartment_name||'';
    case 'arrival':return b.arrival||'';
    case 'breakfast':return b.effective_breakfast_start||b.breakfast_start_date||'';
    case 'halfboard':return b.effective_half_board_start||b.half_board_start_date||'';
    case 'persons':return Number(b.adults||0)+Number(b.children||0);
    default:return '';
  }
}
async function renderMeals(){
  const params={from:state.mealFrom,to:state.mealTo,show_past:state.mealShowPast?1:0,include_unassigned:state.mealIncludeUnassigned?1:0};
  const d=await api('meals',{params});state.mealFrom=d.requested_from||d.from;state.mealTo=d.to;state.mealShowPast=!!d.show_past;state.mealIncludeUnassigned=!!d.include_unassigned;
  const mealBookings=state.mealBookingsSort?sortRows(d.bookings,b=>mealBookingSortValue(b,state.mealBookingsSort),state.mealBookingsSortDir||'asc'):d.bookings;
  const warning=(d.warnings||[]).map(w=>`<div class="alert warning"><b>${esc(w.title||'Hinweis')}</b><br>${esc(w.message||'')}</div>`).join('');
  const dayCards=d.days.map(day=>`<article class="meal-day card"><div class="card-head"><h2>${fmtDate(day.date)}</h2><span class="chip">☕ ${day.summary.breakfast_adults+day.summary.breakfast_children} · 🍽️ ${day.summary.half_adults+day.summary.half_children}</span></div><div class="grid two"><div><h3>☕ Frühstück</h3>${mealTable(day.breakfast,'Frühstück')}</div><div><h3>🍽️ Halbpension</h3>${mealTable(day.half_board,'Halbpension')}</div></div></article>`).join('');
  content.innerHTML=`<div class="toolbar report-toolbar"><label>Von<input type="date" id="mealFrom" value="${esc(state.mealFrom)}"></label><label>Bis<input type="date" id="mealTo" value="${esc(d.to)}"></label><label class="check-inline"><input type="checkbox" id="mealShowPast" ${state.mealShowPast?'checked':''}> vergangene Tage anzeigen</label><label class="check-inline"><input type="checkbox" id="mealIncludeUnassigned" ${state.mealIncludeUnassigned?'checked':''}> nicht zugeordnete Buchungen anzeigen</label><button type="button" class="btn" data-action="meal-apply">Zeitraum anzeigen</button><button type="button" class="btn" data-action="meal-today">Heute + 7 Tage</button><div class="spacer"></div><button type="button" class="btn" data-action="print-meals" data-type="breakfast">☕ Frühstück drucken</button><button type="button" class="btn" data-action="print-meals" data-type="half_board">🍽 HP drucken</button><button type="button" class="btn primary" data-action="print-meals" data-type="all">🖨 Beide Listen</button></div>${warning}<div class="info-box"><b>Angezeigter Zeitraum:</b> ${fmtDate(d.from,false)} – ${fmtDate(d.to,false)}${d.from!==state.mealFrom&&!state.mealShowPast?' · vergangene Tage ausgeblendet':''}. Drucklisten verwenden exakt diese Auswahl.</div><div class="meal-summary"><div class="meal-kpi"><span>☕ Frühstück Erwachsene</span><b>${d.summary.breakfast_adults}</b></div><div class="meal-kpi"><span>🧒 Frühstück Kinder</span><b>${d.summary.breakfast_children}</b></div><div class="meal-kpi"><span>🍽️ HP Erwachsene</span><b>${d.summary.half_adults}</b></div><div class="meal-kpi"><span>🧒 HP Kinder</span><b>${d.summary.half_children}</b></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h2>Leistungs-Buchungen im angezeigten Zeitraum</h2><span class="chip">${d.bookings.length}</span></div><div class="table-wrap"><table><thead><tr>${sortTh('Gast','guest','mealBookings')}${sortTh('Wohnung','apartment','mealBookings')}${sortTh('Aufenthalt','arrival','mealBookings')}${sortTh('Frühstück','breakfast','mealBookings')}${sortTh('Halbpension','halfboard','mealBookings')}${sortTh('Personen','persons','mealBookings')}<th>Prüfung</th><th></th></tr></thead><tbody>${mealBookings.map(b=>`<tr class="${!Number(b.apartment_id)?'warning-row':''}"><td><button type="button" class="guest-text-link" data-action="edit-booking" data-id="${b.id}">${categoryDot(b)}<b>${esc(b.guest_name)}</b></button></td><td>${Number(b.apartment_id)?esc(b.apartment_name||'Nicht zugeordnet'):'⚠ Nicht zugeordnet'}</td><td>${fmtDate(b.arrival,false)}–${fmtDate(b.departure,false)}</td><td>${Number(b.breakfast)?`${fmtDate(b.effective_breakfast_start||b.breakfast_start_date||addDays(b.arrival,1),false)}–${fmtDate(b.effective_breakfast_end||b.breakfast_end_date||b.departure,false)}`:'–'}</td><td>${Number(b.half_board)?`${fmtDate(b.effective_half_board_start||b.half_board_start_date||b.arrival,false)}–${fmtDate(b.effective_half_board_end||b.half_board_end_date||addDays(b.departure,-1),false)}`:'–'}</td><td>${b.adults} Erw. / ${b.children} Kinder</td><td>${(b.meal_warnings||[]).map(x=>`<span class="chip warning">${esc(x)}</span>`).join('')||'<span class="chip success">OK</span>'}</td><td><button type="button" class="btn small" data-action="edit-booking" data-id="${b.id}">Bearbeiten</button></td></tr>`).join('')||'<tr><td colspan="8">Keine Frühstück-/HP-Buchungen im angezeigten Zeitraum.</td></tr>'}</tbody></table></div></div><div class="meal-period-list">${dayCards}</div><div class="info-box" style="margin-top:16px">Diese Liste wird aus den bestehenden Buchungen erzeugt. Standard: nicht zugeordnete Buchungen und vergangene Tage werden ausgeblendet. Beides ist oben auswählbar.</div>`;
}
function mealTable(rows,label){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Wohnung</th><th>Gast</th><th>Erw.</th><th>Kinder</th><th>Hinweis</th></tr></thead><tbody>${rows.map(b=>`<tr class="${!Number(b.apartment_id)?'warning-row':''}"><td>${Number(b.apartment_id)?esc(b.apartment_name||'–'):'⚠ Nicht zugeordnet'}</td><td><button class="guest-text-link" data-action="edit-booking" data-id="${b.id}">${categoryDot(b)}<b>${esc(b.guest_name)}</b></button></td><td>${b.adults}</td><td>${b.children}</td><td>${esc(b.guest_request||b.notes||'')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Kein ${label} im angezeigten Zeitraum.</div>`}

function blockSortValue(b,key){
  switch(key){
    case 'apartment':return b.apartment_name||'';
    case 'start':return b.start_date||'';
    case 'end':return b.end_date||'';
    case 'type':return b.block_type||'';
    case 'reason':return b.reason||'';
    default:return '';
  }
}
function discountCodeSortValue(r,key){
  switch(key){
    case 'code':return r.code||'';
    case 'value':return Number(r.discount_value||0);
    case 'start':return r.start_date||'';
    case 'used':return Number(r.used_count||0);
    case 'status':return Number(r.active)?1:0;
    default:return '';
  }
}
