async function renderPolice(){
  const d=await api('police',{params:{from:state.policeFrom,to:state.policeTo,status:state.policeStatus}});state.policeFrom=d.from;state.policeTo=d.to;
  const missing=d.bookings.reduce((s,b)=>s+Number(b.missing_fields||0),0);
  content.innerHTML=`<div class="toolbar report-toolbar"><label>Von<input type="date" id="policeFrom" value="${d.from}"></label><label>Bis<input type="date" id="policeTo" value="${d.to}"></label><label>Status<select id="policeStatus"><option value="">Alle</option>${[['open','Offen'],['ready','Bereit'],['sent','Gemeldet'],['error','Fehler']].map(([v,l])=>`<option value="${v}" ${state.policeStatus===v?'selected':''}>${l}</option>`).join('')}</select></label><button type="button" class="btn" data-action="police-apply">Anzeigen</button><div class="spacer"></div><button type="button" class="btn" data-action="police-print">🖨 Meldeliste drucken</button><button type="button" class="btn" data-action="police-csv">⬇ CSV exportieren</button></div><div class="grid kpis compact-kpis"><div class="card kpi"><div class="kpi-label">Buchungen</div><div class="kpi-value">${d.bookings.length}</div></div><div class="card kpi"><div class="kpi-label">Reisende erfasst</div><div class="kpi-value">${d.bookings.reduce((s,b)=>s+(b.travellers?.length||0),0)}</div></div><div class="card kpi"><div class="kpi-label">Fehlende Pflichtfelder</div><div class="kpi-value">${missing}</div></div><div class="card kpi"><div class="kpi-label">Gemeldet</div><div class="kpi-value">${d.bookings.filter(b=>b.police_status==='sent').length}</div></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Anreise</th><th>Referenz / Wohnung</th><th>Hauptgast</th><th>Reisende</th><th>Vollständigkeit</th><th>Meldestatus</th><th>Aktionen</th></tr></thead><tbody>${d.bookings.map(b=>`<tr><td><b>${fmtDate(b.arrival)}</b><br><span class="muted small">bis ${fmtDate(b.departure)}</span></td><td><b>${esc(b.reference)}</b><br>${esc(b.apartment_name||'Nicht zugeordnet')}</td><td><button type="button" class="guest-text-link" data-action="edit-booking" data-id="${b.id}">${categoryDot(b)}<b>${esc(b.guest_name)}</b></button></td><td>${b.travellers.length}</td><td>${Number(b.missing_fields)?`<span class="status cancelled">${b.missing_fields} fehlen</span>`:'<span class="status done">Vollständig</span>'}</td><td><select data-police-status="${b.id}">${[['open','Offen'],['ready','Bereit'],['sent','Gemeldet'],['error','Fehler']].map(([v,l])=>`<option value="${v}" ${b.police_status===v?'selected':''}>${l}</option>`).join('')}</select></td><td><button type="button" class="btn small" data-action="open-travellers" data-id="${b.id}">Reisende</button> <a class="btn small" target="_blank" href="../print/registration.php?booking_id=${b.id}">Drucken</a> <button type="button" class="btn small soft" data-action="edit-booking" data-id="${b.id}">Buchung</button></td></tr>`).join('')||'<tr><td colspan="7">Keine Anreisen im gewählten Zeitraum.</td></tr>'}</tbody></table></div><div class="info-box" style="margin-top:14px">Die Meldeliste dient der Erfassung, Prüfung, dem Ausdruck und CSV-Export. Eine behördliche Direktübermittlung wird nicht vorgetäuscht.</div></div>`;
}

