async function loadMasterData(force=false){
  if(!force&&state.cache.houses&&state.cache.apartmentTypes)return state.cache;
  const [houses,types]=await Promise.all([api('houses'),api('apartment_types')]);
  state.cache.houses=houses.houses;state.cache.apartmentTypes=types.apartment_types;return state.cache;
}

async function renderPage(){
  const map={dashboard:renderDashboard,statistics:renderStatistics,calendar:renderCalendar,bookings:renderBookings,houses:renderHouses,apartment_types:renderApartmentTypes,apartments:renderApartments,guests:renderGuests,police:renderPolice,housekeeping:renderHousekeeping,meals:renderMeals,prices:renderPrices,csv:renderCsv,integrations:renderIntegrations,users:renderUsers,system:renderSystem,settings:renderSettings};
  const fn=map[state.page];if(!fn)throw new Error('Unbekannte Seite.');return fn();
}

function yesNo(value){return Number(value)?'Ja':'Nein'}
function roleLabel(role){return({admin:'Administrator',manager:'Leitung',reception:'Rezeption',housekeeping:'Reinigung',readonly:'Nur Lesen'})[role]||role}
function formatBytes(bytes){const units=['B','KB','MB','GB'];let n=Number(bytes)||0,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toLocaleString('de-DE',{maximumFractionDigits:i?1:0})} ${units[i]}`}
function diagnosticBadge(status){return `<span class="diag-badge ${esc(status)}">${status==='ok'?'✓ OK':status==='warning'?'⚠ Warnung':status==='error'?'✕ Fehler':'ℹ Info'}</span>`}

