async function openBooking(id=0,prefill={}){await openBookingV12(id,prefill);enhanceBookingTabs();if(APP.user.role==='readonly'){const form=document.getElementById('bookingForm');form?.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=true);modalRoot.querySelectorAll('.booking-quick-actions button').forEach(el=>el.remove());modalRoot.querySelectorAll('.modal-foot button:not([data-action="close-modal"])').forEach(el=>el.remove());const note=document.createElement('div');note.className='info-box';note.textContent='Dieses Konto besitzt nur Leserechte. Die Buchung kann angesehen, aber nicht verändert werden.';form?.prepend(note)}}
function enhanceBookingTabs(){
  const form=document.getElementById('bookingForm');if(!form)return;const sections=[...form.querySelectorAll(':scope > .booking-sections > section')];if(sections.length<2)return;
  const labels=sections.map((section,index)=>section.querySelector('h3')?.textContent?.trim()||`Bereich ${index+1}`);const nav=document.createElement('div');nav.className='modal-tabs';
  sections.forEach((section,index)=>{section.classList.add('modal-tab-panel');section.dataset.tabIndex=String(index);section.hidden=index!==0;const button=document.createElement('button');button.type='button';button.className=`modal-tab ${index===0?'active':''}`;button.textContent=labels[index].replace(/^[^\p{L}\p{N}]+/u,'');button.addEventListener('click',()=>{sections.forEach((item,i)=>item.hidden=i!==index);nav.querySelectorAll('.modal-tab').forEach((item,i)=>item.classList.toggle('active',i===index))});nav.appendChild(button)});
  form.prepend(nav);
}

