async function renderSystem(){
  const [diag,audit]=await Promise.all([api('diagnostics'),api('audit',{params:{entity_type:state.systemAuditEntity,limit:100}})]);const d=diag.diagnostics;
  content.innerHTML=`<div class="toolbar"><button type="button" class="btn" data-action="refresh-system">↻ Diagnose neu laden</button><button type="button" class="btn primary" data-action="create-backup">💾 Datensicherung erstellen</button><div class="spacer"></div><span class="muted small">Version ${esc(d.version)} · Schema ${esc(d.schema_version)} · ${esc(d.generated_at)}</span></div><div class="grid kpis compact-kpis"><div class="card kpi"><div class="kpi-label">OK</div><div class="kpi-value">${d.summary.ok}</div></div><div class="card kpi"><div class="kpi-label">Warnungen</div><div class="kpi-value">${d.summary.warning}</div></div><div class="card kpi"><div class="kpi-label">Fehler</div><div class="kpi-value">${d.summary.error}</div></div><div class="card kpi"><div class="kpi-label">Backups</div><div class="kpi-value">${d.backups.length}</div></div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-head"><h2>Systemprüfungen</h2></div><div class="diagnostic-list">${d.checks.map(c=>`<div class="diagnostic-row">${diagnosticBadge(c.status)}<div><b>${esc(c.label)}</b><small>${esc(c.message)}</small></div></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Datensicherungen</h2></div><div class="list">${d.backups.map(b=>`<div class="list-item"><div class="avatar">💾</div><div class="grow"><strong>${esc(b.filename)}</strong><small>${esc(b.created_at)} · ${formatBytes(b.size)}</small></div><a class="btn small" href="download_backup.php?file=${encodeURIComponent(b.filename)}">Herunterladen</a></div>`).join('')||'<div class="empty">Noch keine Sicherung vorhanden.</div>'}</div><div class="info-box">Vor einer V2-Migration wird automatisch eine SQL-Sicherung angelegt. Rückspielungen erfolgen bewusst nicht per ungeschütztem Browser-Button.</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h2>Letzte Fehler</h2></div><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Quelle</th><th>Referenz</th><th>Meldung</th></tr></thead><tbody>${d.errors.map(e=>`<tr><td>${esc(e.created_at)}</td><td>${esc(e.source)}</td><td><code>${esc(e.request_id)}</code></td><td>${esc(e.message)}</td></tr>`).join('')||'<tr><td colspan="4">Keine protokollierten Fehler.</td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h2>Änderungsverlauf</h2><select id="auditEntity"><option value="">Alle Bereiche</option>${['house','apartment_type','apartment','guest','guest_category','booking','season','season_period','season_price_matrix','special_price','booking_channel','housekeeping_task','housekeeping_team','housekeeping_member','smtp_settings','user','system_backup'].map(v=>`<option value="${v}" ${state.systemAuditEntity===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Benutzer</th><th>Bereich</th><th>Aktion</th><th>Hinweis</th></tr></thead><tbody>${audit.entries.map(e=>`<tr><td>${esc(e.created_at)}</td><td>${esc(e.user_name||'System')}</td><td>${esc(e.entity_type)} #${esc(e.entity_id||'')}</td><td>${esc(e.action)}</td><td>${esc(e.note||'')}</td></tr>`).join('')||'<tr><td colspan="5">Noch keine Änderungen protokolliert.</td></tr>'}</tbody></table></div></div>`;
}

async function handleSupplementalAction(a,el){
  if(a==='print-window'){window.print();return true}
  if(a==='calculate-price-v2'){const f=document.getElementById('bookingForm');if(!f?.apartment_id.value)throw new Error('Bitte zuerst ein Apartment auswählen.');const o=formObject(f);o.breakfast_days=o.breakfast&&o.breakfast_start_date&&o.breakfast_end_date?diffDays(o.breakfast_start_date,addDays(o.breakfast_end_date,1)):0;o.half_board_days=o.half_board&&o.half_board_start_date&&o.half_board_end_date?diffDays(o.half_board_start_date,addDays(o.half_board_end_date,1)):0;const out=await api('price_quote',{method:'POST',data:o});f.total_price.value=out.price;document.getElementById('priceBreakdown').innerHTML=priceBreakdownHtml(out.details);toast('Preis einschließlich Zuschlägen und Rabatten berechnet.');return true}
  if(a==='house-apply-v2'){state.houseFrom=document.getElementById('houseFrom').value;state.houseTo=document.getElementById('houseTo').value;state.houseFilters={apartment_id:document.getElementById('houseApartment').value,status:document.getElementById('houseStatus').value,task_type:document.getElementById('houseType').value,assigned_to:document.getElementById('houseStaff').value,priority:document.getElementById('housePriority').value};await renderHousekeeping();return true}
  if(a==='print-housekeeping'){printUrl('../print/housekeeping.php',{from:document.getElementById('houseFrom').value,to:document.getElementById('houseTo').value,...state.houseFilters});return true}
  if(a==='print-meals'){printUrl('../print/meals.php',{from:document.getElementById('mealFrom').value,to:document.getElementById('mealTo').value,type:el.dataset.type,show_past:document.getElementById('mealShowPast')?.checked?1:0,include_unassigned:document.getElementById('mealIncludeUnassigned')?.checked?1:0});return true}
  if(a==='new-length-discount'){openLengthDiscount();return true}if(a==='edit-length-discount'){openLengthDiscount(el.dataset.id);return true}if(a==='delete-length-discount'){if(confirm('Staffelrabatt löschen?')){await api('delete_length_discount',{method:'POST',data:{id:el.dataset.id}});toast('Staffelrabatt gelöscht.');await renderPrices()}return true}
  if(a==='new-discount-code'){openDiscountCode();return true}if(a==='edit-discount-code'){openDiscountCode(el.dataset.id);return true}if(a==='delete-discount-code'){if(confirm('Rabattcode löschen?')){await api('delete_discount_code',{method:'POST',data:{id:el.dataset.id}});toast('Rabattcode gelöscht.');await renderPrices()}return true}
  if(a==='open-travellers'){await openTravellers(el.dataset.id);return true}if(a==='add-traveller'){const box=document.getElementById('travellerRows');box.insertAdjacentHTML('beforeend',travellerRow({},box.children.length));return true}if(a==='remove-traveller'){el.closest('[data-traveller-row]')?.remove();document.querySelectorAll('[data-traveller-number]').forEach((n,i)=>n.textContent=i+1);return true}
  if(a==='police-apply'){state.policeFrom=document.getElementById('policeFrom').value;state.policeTo=document.getElementById('policeTo').value;state.policeStatus=document.getElementById('policeStatus').value;await renderPolice();return true}if(a==='police-print'){printUrl('../print/police_list.php',{from:document.getElementById('policeFrom').value,to:document.getElementById('policeTo').value,status:state.policeStatus});return true}if(a==='police-csv'){printUrl('../print/police_csv.php',{from:document.getElementById('policeFrom').value,to:document.getElementById('policeTo').value,status:state.policeStatus});return true}
  if(a==='stats-apply'){state.statsFrom=document.getElementById('statsFrom').value;state.statsTo=document.getElementById('statsTo').value;await renderStatistics();return true}
  if(a==='new-house'){await openHouse();return true}if(a==='edit-house'){await openHouse(el.dataset.id);return true}if(a==='delete-house'){if(confirm('Haus wirklich löschen?')){const r=await api('delete_house',{method:'POST',data:{id:el.dataset.id}});toast(r.message);state.cache.houses=null;await renderHouses()}return true}
  if(a==='new-apartment-type'){await openApartmentType();return true}if(a==='edit-apartment-type'){await openApartmentType(el.dataset.id);return true}if(a==='delete-apartment-type'){if(confirm('Wohnungstyp wirklich löschen?')){const r=await api('delete_apartment_type',{method:'POST',data:{id:el.dataset.id}});toast(r.message);state.cache.apartmentTypes=null;await renderApartmentTypes()}return true}
  if(a==='new-user'){await openUser();return true}if(a==='edit-user'){await openUser(el.dataset.id);return true}if(a==='delete-user'){if(confirm('Benutzerkonto deaktivieren?')){const r=await api('delete_user',{method:'POST',data:{id:el.dataset.id}});toast(r.message);await renderUsers()}return true}
  if(a==='refresh-system'){await renderSystem();return true}if(a==='create-backup'){const r=await api('create_backup',{method:'POST',data:{}});toast(r.message);await renderSystem();return true}
  if(a==='generate-staypilot-export-key'){const r=await api('generate_staypilot_export_key_v1',{method:'POST',data:{}});modal('Neuer StayPilot-Export-Schlüssel',`<div class="alert warning"><b>Wichtig:</b> Dieser Schlüssel wird nur einmal angezeigt. Jetzt kopieren und in der Mietverwaltung unter Einstellungen → Sicherheit → „StayPilot-Anbindung" einfügen.</div><div class="field" style="margin-top:12px"><label>Schlüssel</label><input type="text" readonly value="${esc(r.key)}"></div>`,`<button class="btn primary" type="button" data-action="copy-staypilot-key" data-key="${esc(r.key)}">Kopieren</button><button class="btn" type="button" data-action="close-modal">Schließen</button>`,true);await renderSettings();return true}
  if(a==='copy-staypilot-key'){try{await navigator.clipboard.writeText(el.dataset.key||'');toast('Schlüssel kopiert.');}catch(_){}return true}
  return false;
}

async function handleSupplementalSubmit(form){
  const formName=formIdentifier(form);
  if(formName==='priceFormV2'){const apartments=[...form.querySelectorAll('[data-price-row-v2]')].map(row=>{const o={id:row.dataset.priceRowV2};row.querySelectorAll('input[name]').forEach(x=>o[x.name]=x.value);return o});const r=await api('save_prices',{method:'POST',data:{apartments}});toast(r.message);await renderPrices();return true}
  if(formName==='lengthDiscountForm'){const r=await api('save_length_discount',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast(r.message);await renderPrices();return true}
  if(formName==='discountCodeForm'){const r=await api('save_discount_code',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast(r.message);await renderPrices();return true}
  if(formName==='travellersFormV2'){const r=await api('save_travellers',{method:'POST',data:{booking_id:form.booking_id.value,travellers:collectTravellers(form)}});window.stayPilotModal.markClean();closeModal(true);toast(r.message);if(state.page==='police')await renderPolice();else await openBooking(form.booking_id.value);return true}
  if(formName==='houseForm'){const r=await api('save_house',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast(r.message);state.cache.houses=null;await renderHouses();return true}
  if(formName==='apartmentTypeForm'){const r=await api('save_apartment_type',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast(r.message);state.cache.apartmentTypes=null;await renderApartmentTypes();return true}
  if(formName==='userForm'){const r=await api('save_user',{method:'POST',data:formObject(form)});window.stayPilotModal.markClean();closeModal(true);toast(r.message);await renderUsers();return true}
  return false;
}

async function handleSupplementalChange(event){
  if(event.target.matches('[data-police-status]')){const r=await api('police_status',{method:'POST',data:{id:event.target.dataset.policeStatus,status:event.target.value}});toast(r.message);return true}
  if(event.target.id==='auditEntity'){state.systemAuditEntity=event.target.value;await renderSystem();return true}
  if(event.target.name==='apartment_type_id'&&document.getElementById('apartmentForm')){const form=document.getElementById('apartmentForm');const type=state.cache.apartmentTypes?.find(t=>String(t.id)===String(event.target.value));if(type&&Number(form.elements.id?.value||0)===0){form.max_guests.value=type.max_occupancy;form.bedrooms.value=type.bedrooms;form.base_price.value=type.standard_price;form.cleaning_fee.value=type.cleaning_fee;form.breakfast_price.value=type.breakfast_price;form.half_board_price.value=type.half_board_price;form.parking_price_per_night.value=type.parking_price;form.pet_price_per_night.value=type.pet_price;form.extra_bed_price_per_night.value=type.extra_bed_price;form.baby_bed_fee.value=type.baby_bed_price}return true}
  return false;
}

navigate(APP.user.role==='housekeeping'?'housekeeping':'dashboard');
